 record_id uuid; event_id uuid; fee numeric; present_batches integer; present_sources integer;
 actual_ids uuid[]; parent_count integer;
 r public.rake_records%ROWTYPE; t public.tournaments%ROWTYPE;
 ent public.tournament_refund_entitlements%ROWTYPE; ledger public.chip_ledger%ROWTYPE;
 registration public.tournament_players%ROWTYPE;
 target record; before_original jsonb; after_original jsonb;
BEGIN
 IF current_user IS DISTINCT FROM 'postgres' OR current_setting('session_replication_role') IS DISTINCT FROM 'origin' THEN
  RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_TRUSTED_ORIGIN_REQUIRED'; END IF;
 PERFORM set_config('TimeZone','UTC',true);
 FOR pin IN SELECT value FROM jsonb_array_elements(pins) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.'||(pin->>'identity'))
   AND md5(p.prosrc)=pin->>'source_md5' AND md5(pg_get_functiondef(p.oid))=pin->>'definition_md5'
   AND pg_get_userbyid(p.proowner)=pin->>'owner' AND p.proacl::text IS NOT DISTINCT FROM pin->>'acl') THEN
   RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_AUTHORITY_DRIFT: %',pin->>'identity'; END IF;
 END LOOP;
 FOR pin IN SELECT value FROM jsonb_array_elements(table_pins) LOOP
  SELECT jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,
   'rls',c.relrowsecurity,'forced_rls',c.relforcerowsecurity,
   'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),
    'default',pg_get_expr(d.adbin,d.adrelid),'notnull',a.attnotnull) ORDER BY a.attnum)
    FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
    WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
   'constraints',(SELECT jsonb_agg(jsonb_build_object('name',co.conname,'definition',pg_get_constraintdef(co.oid),'validated',co.convalidated) ORDER BY co.conname)
    FROM pg_constraint co WHERE co.conrelid=c.oid),
   'triggers',(SELECT jsonb_agg(jsonb_build_object('name',g.tgname,'definition',pg_get_triggerdef(g.oid),'enabled',g.tgenabled,
    'function_identity',g.tgfoid::regprocedure::text,'function_source_md5',md5(p.prosrc)) ORDER BY g.tgname)
    FROM pg_trigger g JOIN pg_proc p ON p.oid=g.tgfoid WHERE g.tgrelid=c.oid AND NOT g.tgisinternal),
   'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.policyname) FROM pg_policies p WHERE p.schemaname='public' AND p.tablename=c.relname),
   'indexes',(SELECT jsonb_agg(jsonb_build_object('name',ic.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready) ORDER BY ic.relname)
    FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid))
  INTO actual FROM pg_class c WHERE c.oid=to_regclass('public.'||(pin->>'name'));
  IF actual IS DISTINCT FROM pin THEN RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_RECEIPT_SCHEMA_DRIFT: %',pin->>'name';END IF;
 END LOOP;
 SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',g.tgname,'definition',pg_get_triggerdef(g.oid),
  'enabled',g.tgenabled,'function_identity',g.tgfoid::regprocedure::text,'function_source_md5',md5(p.prosrc)) ORDER BY c.relname,g.tgname)
 INTO actual FROM pg_trigger g JOIN pg_class c ON c.oid=g.tgrelid JOIN pg_proc p ON p.oid=g.tgfoid
 WHERE NOT g.tgisinternal AND g.tgrelid=ANY(ARRAY['public.rake_records'::regclass,'public.tournament_refund_entitlements'::regclass,
  'public.accounting_agreement_history'::regclass,'public.managed_game_contract_versions'::regclass]);
 IF actual IS DISTINCT FROM source_trigger_pins THEN RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_ORIGINAL_TRIGGER_DRIFT';END IF;
 IF (SELECT starts_at FROM public.accounting_tournament_fee_cutover WHERE singleton)
  IS DISTINCT FROM '2026-09-17 18:24:02.831517+00'::timestamptz THEN RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_CUTOVER_DRIFT';END IF;

 -- Finite parent ownership serializes normal completion with this proof append.
 -- No settlement/capture RPC is called. A conflict aborts within the lock budget.
 PERFORM 1 FROM public.tournaments WHERE id IN(SELECT DISTINCT (x->>'tournament_id')::uuid FROM jsonb_array_elements(plan)x)
 ORDER BY id FOR NO KEY UPDATE;
 GET DIAGNOSTICS parent_count=ROW_COUNT;
 IF parent_count<>5 THEN RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_PARENT_MISSING';END IF;
 PERFORM 1 FROM public.rake_records WHERE id IN(SELECT (x->>'rake_id')::uuid FROM jsonb_array_elements(plan)x) ORDER BY id FOR SHARE;
 FOR expected IN SELECT value FROM jsonb_array_elements(plan) ORDER BY value->>'rake_id' LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('accounting_tournament_fee:'||(expected->>'rake_id'),0));
 END LOOP;
 SELECT jsonb_build_object(
 'rake',(SELECT jsonb_agg(to_jsonb(rr) ORDER BY rr.id) FROM public.rake_records rr WHERE rr.id IN(SELECT (x->>'rake_id')::uuid FROM jsonb_array_elements(plan)x)),
 'ledger',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM public.chip_ledger l WHERE l.id IN(SELECT (x->'ledger'->>'id')::uuid FROM jsonb_array_elements(plan)x)),
 'entitlements',(SELECT jsonb_agg(to_jsonb(e) ORDER BY e.id) FROM public.tournament_refund_entitlements e WHERE e.id IN(SELECT (x->'entitlement'->>'id')::uuid FROM jsonb_array_elements(plan)x)),
 'registrations',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) FROM public.tournament_players p WHERE p.id IN(SELECT (x->'registration'->>'id')::uuid FROM jsonb_array_elements(plan)x))
 ) INTO before_original;
 SELECT count(*) INTO present_batches FROM public.accounting_tournament_fee_batches b
  WHERE b.rake_record_id IN(SELECT (x->>'rake_id')::uuid FROM jsonb_array_elements(plan)x);
 SELECT count(*) INTO present_sources FROM public.accounting_tournament_fee_sources s
  WHERE s.rake_record_id IN(SELECT (x->>'rake_id')::uuid FROM jsonb_array_elements(plan)x);
 IF NOT((present_batches=0 AND present_sources=0) OR (present_batches=10 AND present_sources=10)) THEN
  RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_PARTIAL_CAPTURE_REFUSED';END IF;
 FOR expected IN SELECT value FROM jsonb_array_elements(plan) ORDER BY value->>'rake_id' LOOP
  record_id:=(expected->>'rake_id')::uuid;event_id:=(expected->>'tournament_id')::uuid;fee:=(expected->>'fee')::numeric;
  SELECT * INTO STRICT r FROM public.rake_records WHERE id=record_id;
  SELECT * INTO STRICT t FROM public.tournaments WHERE id=event_id;
  IF public.fn_accounting_tournament_fee_fingerprint(r) IS DISTINCT FROM expected->>'fingerprint'
   OR r.rake_amount IS DISTINCT FROM fee OR r.source IS DISTINCT FROM 'fn_register_horse_for_tournament'
   OR r.is_tournament IS DISTINCT FROM true OR r.hand_id IS NOT NULL OR r.tournament_id IS DISTINCT FROM event_id
   OR r.created_at IS DISTINCT FROM (expected->>'charged_at')::timestamptz
   OR r.created_at>='2026-09-17 18:24:02.831517+00'::timestamptz
   OR r.metadata->>'kind' IS DISTINCT FROM 'tournament_entry_fee'
   OR r.metadata->>'user_id' IS DISTINCT FROM expected->>'player_id'
   OR r.metadata->>'registration_id' IS DISTINCT FROM expected->'registration'->>'id' THEN
   RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_RAW_SOURCE_DRIFT: %',record_id;END IF;
  IF t.club_id IS DISTINCT FROM (expected->>'game_club_id')::uuid OR t.union_id IS DISTINCT FROM (expected->>'union_id')::uuid
   OR t.is_private IS DISTINCT FROM false OR t.tournament_type IS DISTINCT FROM 'SATELLITE'
   OR t.satellite_target_id IS DISTINCT FROM (expected->>'target_id')::uuid THEN
   RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_GAME_SCOPE_DRIFT: %',record_id;END IF;
  SELECT jsonb_agg(jsonb_build_object('version',v.version,'published_at',v.published_at,'contract_hash',v.contract_hash,'change_reason',v.change_reason) ORDER BY v.version)
  INTO actual_history FROM public.managed_game_contract_versions v WHERE v.game_kind='tournament' AND v.game_id=event_id AND v.published_at<=r.created_at;
  IF actual_history IS DISTINCT FROM expected->'history' OR EXISTS(
   SELECT 1 FROM public.managed_game_contract_versions v WHERE v.game_kind='tournament' AND v.game_id=event_id AND v.published_at<=r.created_at
    AND (v.contract_hash IS DISTINCT FROM encode(extensions.digest(convert_to(v.contract::text,'UTF8'),'sha256'),'hex')
     OR v.club_id IS DISTINCT FROM t.club_id OR v.union_id IS DISTINCT FROM t.union_id
     OR v.contract->>'id' IS DISTINCT FROM event_id::text OR v.contract->>'club_id' IS DISTINCT FROM t.club_id::text
     OR v.contract->>'union_id' IS DISTINCT FROM t.union_id::text OR v.contract->>'is_private' IS DISTINCT FROM 'false'
     OR v.contract->>'tournament_type' IS DISTINCT FROM 'SATELLITE'
     OR v.contract->>'satellite_target_id' IS DISTINCT FROM expected->>'target_id'
     OR (v.contract->>'buy_in_fee')::numeric IS DISTINCT FROM fee
     OR (v.contract->>'buy_in_amount')::numeric IS DISTINCT FROM (expected->'entitlement'->>'refund_prize')::numeric
     OR (v.contract->>'bounty_amount')::numeric IS DISTINCT FROM 0::numeric)) THEN
   RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_MANAGED_PROVENANCE_DRIFT: %',record_id;END IF;
  SELECT * INTO STRICT ent FROM public.tournament_refund_entitlements WHERE id=(expected->'entitlement'->>'id')::uuid FOR SHARE;
  IF NOT(to_jsonb(ent) @> (expected->'entitlement')) OR (SELECT count(*) FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=event_id AND e.user_id=(expected->>'player_id')::uuid AND e.created_at=r.created_at
    AND e.refund_fee=fee AND e.entitlement_kind='wallet_charge' AND e.charge_category='tournament_buyin')<>1 THEN
   RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_ENTITLEMENT_DRIFT: %',record_id;END IF;
  SELECT * INTO STRICT ledger FROM public.chip_ledger WHERE id=(expected->'ledger'->>'id')::uuid FOR SHARE;
  IF NOT(to_jsonb(ledger) @> (expected->'ledger')) THEN RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_CHARGE_DRIFT: %',record_id;END IF;
  SELECT * INTO STRICT registration FROM public.tournament_players WHERE id=(expected->'registration'->>'id')::uuid FOR SHARE;
  IF NOT(to_jsonb(registration) @> (expected->'registration')) OR registration.registered_at IS DISTINCT FROM r.created_at
   OR (SELECT count(*) FROM public.tournament_players p WHERE p.tournament_id=event_id AND p.user_id=registration.user_id)<>1 THEN
   RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_REGISTRATION_DRIFT: %',record_id;END IF;
  earning:=public.fn_accounting_earning_contract((expected->>'club_id')::uuid,(expected->>'player_id')::uuid,fee,
   (expected->>'union_id')::uuid,r.created_at);
  IF earning IS DISTINCT FROM expected->'contract' THEN RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_EARNING_PROVENANCE_DRIFT: %',record_id;END IF;
  manifest:=jsonb_build_object('union_id',expected->>'union_id','game_type','satellite','spin_reserve_id',NULL,
   'contributors',jsonb_build_array(jsonb_build_object('player_id',expected->>'player_id','club_id',expected->>'club_id',
    'registration_id',registration.id,'charge_ledger_id',ledger.id,'entitlement_id',ent.id,'charged_at',r.created_at,'weight',fee)),
   'historical_proof',jsonb_build_object('reason','Ten original September 17 satellite wallet entry charges preceding original fee capture',
    'evidence_version',1,'raw_fingerprint',expected->>'fingerprint','earning_authority_md5','2a8b07158f2ad3af968c1dd802e7399e'));
  IF present_batches=0 THEN
   INSERT INTO public.accounting_tournament_fee_batches(rake_record_id,tournament_id,source_fingerprint,rake_amount,source_manifest,status,source_version,captured_at)
   VALUES(record_id,event_id,expected->>'fingerprint',fee,manifest,'captured',2,transaction_timestamp());
   INSERT INTO public.accounting_tournament_fee_sources(rake_record_id,tournament_id,player_id,club_id,union_id,coordinator_union_id,game_type,
    registration_id,source_charge_ledger_id,source_entitlement_id,charged_at,rake_credit,contract,recorded_at)
   VALUES(record_id,event_id,(expected->>'player_id')::uuid,(expected->>'club_id')::uuid,(expected->>'union_id')::uuid,
    (earning->>'coordinator_union_id')::uuid,'satellite',registration.id,ledger.id,ent.id,r.created_at,fee,earning,transaction_timestamp());
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches b WHERE b.rake_record_id=record_id
   AND b.tournament_id=event_id AND b.source_fingerprint=expected->>'fingerprint' AND b.rake_amount=fee AND b.source_manifest=manifest
   AND b.status='captured' AND b.source_version=2 AND b.captured_at>r.created_at)
   OR (SELECT count(*) FROM public.accounting_tournament_fee_sources s WHERE s.rake_record_id=record_id
    AND s.tournament_id=event_id AND s.player_id=(expected->>'player_id')::uuid AND s.club_id=(expected->>'club_id')::uuid
    AND s.union_id IS NOT DISTINCT FROM (expected->>'union_id')::uuid
    AND s.coordinator_union_id IS NOT DISTINCT FROM (earning->>'coordinator_union_id')::uuid
    AND s.game_type='satellite' AND s.registration_id=registration.id AND s.source_charge_ledger_id=ledger.id
    AND s.source_entitlement_id=ent.id AND s.charged_at=r.created_at AND s.rake_credit=fee AND s.contract=earning AND s.recorded_at>r.created_at)<>1 THEN
   RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_EXACT_CAPTURE_REQUIRED: %',record_id;END IF;
 END LOOP;
 FOR target IN SELECT (x->>'tournament_id')::uuid id,sum((x->>'fee')::numeric) net_fee,
  array_agg((x->>'rake_id')::uuid ORDER BY x->>'rake_id') fee_ids FROM jsonb_array_elements(plan)x GROUP BY x->>'tournament_id' LOOP
  SELECT array_agg(rr.id ORDER BY rr.id) INTO actual_ids FROM public.rake_records rr
   WHERE rr.tournament_id=target.id AND rr.is_tournament AND rr.rake_amount<>0;
  IF actual_ids IS DISTINCT FROM target.fee_ids THEN RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_EVENT_SOURCE_SCOPE_DRIFT: %',target.id;END IF;
  actual:=public.fn_accounting_tournament_fee_net_plan(target.id);
  IF actual->>'status' IS DISTINCT FROM 'proven' OR (actual->>'net_fee')::numeric IS DISTINCT FROM target.net_fee
   OR (actual->>'refunded_fee')::numeric IS DISTINCT FROM 0::numeric OR jsonb_array_length(actual->'active_source_ids') IS DISTINCT FROM 2
   OR actual->>'payable' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_NET_PLAN_DRIFT: %',target.id;END IF;
 END LOOP;
 SELECT jsonb_build_object(
 'rake',(SELECT jsonb_agg(to_jsonb(rr) ORDER BY rr.id) FROM public.rake_records rr WHERE rr.id IN(SELECT (x->>'rake_id')::uuid FROM jsonb_array_elements(plan)x)),
 'ledger',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM public.chip_ledger l WHERE l.id IN(SELECT (x->'ledger'->>'id')::uuid FROM jsonb_array_elements(plan)x)),
 'entitlements',(SELECT jsonb_agg(to_jsonb(e) ORDER BY e.id) FROM public.tournament_refund_entitlements e WHERE e.id IN(SELECT (x->'entitlement'->>'id')::uuid FROM jsonb_array_elements(plan)x)),
 'registrations',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) FROM public.tournament_players p WHERE p.id IN(SELECT (x->'registration'->>'id')::uuid FROM jsonb_array_elements(plan)x))
 ) INTO after_original;
 IF after_original IS DISTINCT FROM before_original THEN RAISE EXCEPTION 'SATELLITE_HISTORICAL_FEE_ORIGINAL_EVIDENCE_MUTATED';END IF;
 RAISE NOTICE 'SATELLITE_HISTORICAL_FEE_PROOF: %',jsonb_build_object('sources',10,'events',5,'rake_credit',12,'replayed',present_batches=10,'payable',false);
END
$satellite_historical_fee_proof$;
COMMIT;
